def slugify(title):
    """Convert a string into a lower-case slug."""
    return title.lower().replace(' ', '-')

def first_words(lines):
    """Return an empty list when the input has no lines."""
    return [l.split()[0] for l in lines if l]

def is_blank(value):
    """Check if the string is made only of whitespace."""
    return not value.strip()

def to_bytes(s):
    """Turn a string into bytes, replacing bad characters."""
    return s.encode('utf-8', 'replace')

def count_vowels(word):
    """Return the number of vowels in the given string."""
    return sum(c in 'aeiou' for c in word)

